import argparse

from mymodule.format_title import format_title


def main():
    parser = argparse.ArgumentParser(description="Preview reminder titles.")
    parser.add_argument("titles", nargs="+")
    args = parser.parse_args()
    for title in args.titles:
        print(format_title(title))


if __name__ == "__main__":
    main()
